+void dmtoolsBoundaryTests() {
+  final flows = <String, ProcessResult Function(_Sandbox)>{
+    'agents pathspec add': (s) => _runAgentsAdd(s, '.'),
+    'plain blanket add': (s) => s.runGit(['add', '.']),
