+        );
+      });
+    });
+  });
+}
+
+/// Anything under `.dmtools/` outside the trackable boundary: session and
+/// trace artifacts, nested runner subdirs, unlisted files.
+bool _isDmtoolsArtifact(String path) {
+  if (path == '.dmtools/config.js') return false;
